SELECT mkt.INDX_SNAME AS `指数名称`, mkt.SECCODE AS `指数代码`, '2025-01-01' AS `区间起始日期`, '2025-12-31' AS `区间截止日期`, ROUND(start.LCLOSE, 2) AS `年初首日昨收价`, ROUND(end.TCLOSE, 2) AS `年末收盘价`, ROUND(CASE WHEN start.LCLOSE <> 0 THEN (end.TCLOSE - start.LCLOSE) / start.LCLOSE * 100 ELSE NULL END, 2) AS `2025年全年涨跌幅(%)` FROM GET_INDX_GEN_INFO gen JOIN INDX_MKT mkt ON gen.INNER_CODE = mkt.INNER_CODE AND mkt.ISVALID = 1 AND mkt.TRADEDATE = (SELECT MAX(TRADEDATE) FROM INDX_MKT WHERE TRADEDATE >= '2025-01-01' AND TRADEDATE <= '2025-12-31' AND ISVALID = 1 AND INNER_CODE = gen.INNER_CODE) JOIN INDX_MKT start ON gen.INNER_CODE = start.INNER_CODE AND start.ISVALID = 1 AND start.TRADEDATE = (SELECT MIN(TRADEDATE) FROM INDX_MKT WHERE TRADEDATE >= '2025-01-01' AND TRADEDATE <= '2025-12-31' AND ISVALID = 1 AND INNER_CODE = gen.INNER_CODE) JOIN INDX_MKT end ON gen.INNER_CODE = end.INNER_CODE AND end.ISVALID = 1 AND end.TRADEDATE = (SELECT MAX(TRADEDATE) FROM INDX_MKT WHERE TRADEDATE >= '2025-01-01' AND TRADEDATE <= '2025-12-31' AND ISVALID = 1 AND INNER_CODE = gen.INNER_CODE) WHERE gen.INDX_SNAME LIKE '%中证军工%' AND gen.USE_STATUS = '使用' AND gen.ISVALID = 1 AND start.LCLOSE IS NOT NULL AND end.TCLOSE IS NOT NULL;
